export interface Transfer {
  /** Present and true when the simulated hub of a test site gave this answer. No real system was reached. */
  simulated?: boolean;
  /** Id with the `trf_` prefix. */
  id: string;
  plan_id: string;
  connection_id: string;
  site_id: string;
  verb: WriteVerb;
  status: TransferStatus;
  status_reason?: string | null;
  /** Present only while the transfer waits at the hub for a step of a person; `status` is then `queued`. `patient_context`, with `status_reason: needs_kontext`: T2med writes only for the patient opened from T2med, so a member opens the patient in T2med and the hub writes then. Values may be added. Addition of 09.11.2026. */
  waiting_for?: string;
  /** The signed release. In every transfer answer `patient_confirmed` names the patient by `id` only; names and birth date go only to the hub. The cloud deletes the plan content and the full release when the transfer reaches a final state (`completed`, `partially_completed`, `failed`, `expired`, or settled with `transfers.resolve`). */
  release: Release;
  operations: OperationResult[];
  history: TransferHistory[];
  expires_at: string;
  created_at: string;
  updated_at: string;
}

/** A verb that writes into the target system. It always goes plan, release, transfer. */
export type WriteVerb = "record.write" | "record.write.batch" | "diagnosis.write" | "diagnosis.write.text" | "medication.order" | "document.attach" | "appointment.book" | "appointment.cancel" | "referral.order" | "billing.propose" | (string & {});

