/** One entry of the patient's record as the system holds it. Every system fills the required fields. `kennzeichen`, `meaning`, `source` and `field` are filled where the system has them (the BDT systems MEDICAL OFFICE and QUINCY) and left out elsewhere. Clients must accept entries without them. Addition of 11.11.2026. */
export interface RecordEntry {
  /** Stable for the same entry of the same file or system answer. Holds no patient data. */
  id: string;
  patient_id: string;
  /** The slot of `record.slots` the entry belongs to, when it belongs to one a write can target. Filter with `slot_ids`. */
  slot_id?: string | null;
  /** The name the system shows for the entry's kind, for example `Anamnese (A)` or `Freitext`. */
  slot_label?: string | null;
  date: string;
  author?: string | null;
  text: string;
  /** The system's Textkennzeichen of the entry (QUINCY: `A`, `B`, `DD`, ...), null when the entry has none. Systems without Kennzeichen leave it out. Filter with `kennzeichen`. */
  kennzeichen?: string | null;
  /** What the entry is, the same words for every system: `anamnesis`, `finding`, `therapy`, `diagnosis_acute`, `diagnosis_permanent`, `medication`, `other`. Taken from the Kennzeichen (QUINCY) or from the field or category name (MEDICAL OFFICE). New values may appear; treat an unknown value as `other`. Filter with `kennzeichen`. */
  meaning?: "anamnesis" | "finding" | "therapy" | "diagnosis_acute" | "diagnosis_permanent" | "medication" | "other" | (string & {});
  /** Where in the system's data the text stood. BDT systems: `field` (a standard text field, see `field`), `result` (the text of a GDT result), `category` (a free category), and for QUINCY how the category named its Kennzeichen: `category_code` (`A`), `category_code_name` (`A#Anamnese`) or `category_name` (`Anamnese`). New values may appear. */
  source?: "field" | "result" | "category" | "category_code" | "category_code_name" | "category_name" | (string & {});
  /** BDT systems only. The BDT field that opened the text, for example 6220 (Befund) or 6330 (the first free category). */
  field?: number | null;
}

/** The days the system's export file holds. MEDICAL OFFICE writes the Krankenblatt from the date the person chose in "Datenexport ab": entries before `from` are not in the answer because the file does not have them, not because the patient has none. Left out by systems that answer from their whole record. Addition of 11.11.2026. */
